DB.StartTransaction();
var job = DB.LoadNextJob();
var csv = LoadFile(job.Source);
var records = ConvertCsvToRecords(csv);
WriteFile(job.Destination, records.ToString());
DB.MarkJobAsCompleted(job);
DB.Commit();

// 2つの操作がバラバラのトランザクション
